function shapeArabic(text){
 const rows=[[0x621,0xfe80,1],[0x622,0xfe81,2],[0x623,0xfe83,2],[0x624,0xfe85,2],[0x625,0xfe87,2],[0x626,0xfe89,4],[0x627,0xfe8d,2],[0x628,0xfe8f,4],[0x629,0xfe93,2],[0x62a,0xfe95,4],[0x62b,0xfe99,4],[0x62c,0xfe9d,4],[0x62d,0xfea1,4],[0x62e,0xfea5,4],[0x62f,0xfea9,2],[0x630,0xfeab,2],[0x631,0xfead,2],[0x632,0xfeaf,2],[0x633,0xfeb1,4],[0x634,0xfeb5,4],[0x635,0xfeb9,4],[0x636,0xfebd,4],[0x637,0xfec1,4],[0x638,0xfec5,4],[0x639,0xfec9,4],[0x63a,0xfecd,4],[0x641,0xfed1,4],[0x642,0xfed5,4],[0x643,0xfed9,4],[0x644,0xfedd,4],[0x645,0xfee1,4],[0x646,0xfee5,4],[0x647,0xfee9,4],[0x648,0xfeed,2],[0x649,0xfeef,2],[0x64a,0xfef1,4]];
 const map=new Map(rows.map(([c,start,n])=>[String.fromCharCode(c),{start,n}]));
 return String(text).replace(/[\u064B-\u065F\u0670\u0640]/g,'').split('\n').map(line=>{
  const chars=Array.from(line),shaped=chars.map((ch,i)=>{
   const cur=map.get(ch);if(!cur)return ch;
   const prev=map.get(chars[i-1]),next=map.get(chars[i+1]);
   const p=!!prev&&prev.n===4&&cur.n>=2,n=cur.n===4&&!!next&&next.n>=2;
   return String.fromCharCode(cur.start+(p&&n?3:n?2:p?1:0));
  });
  return shaped.reverse().join('').replace(/[A-Za-z0-9٠-٩][A-Za-z0-9٠-٩ .:/_-]*/g,x=>Array.from(x).reverse().join(''));
 }).join('\n');
}
function wrapTitle(text){
 const words=String(text).replace(/\s+/g,' ').trim().split(' '),lines=[];let current='';
 for(const word of words){if(current&&(current+' '+word).length>32){lines.push(current);current=word;}else current+=(current?' ':'')+word;}
 if(current)lines.push(current);
 return lines.slice(0,3).join('\n');
}


function parseImagePlan(raw) {
 if(raw&&typeof raw==='object')return {plan:raw,repaired:false};
 const text=String(raw??'').trim().replace(/^\x60\x60\x60(?:json)?\s*/i,'').replace(/\s*\x60\x60\x60$/,'');
 try{return {plan:JSON.parse(text),repaired:false};}catch{}
 let repaired='',quoted=false,escaped=false,previous='';
 for(let i=0;i<text.length;i++){
  const c=text[i];
  if(quoted){repaired+=c;if(escaped)escaped=false;else if(c==='\\')escaped=true;else if(c==='"'){quoted=false;previous='"';}continue;}
  if(c==='"'){quoted=true;repaired+=c;continue;}
  if(c==='{'&&previous==='{')continue;
  if(c===','){let next=i+1;while(/\s/.test(text[next]||'')&&next<text.length)next++;if(text[next]==='}'||text[next]===']')continue;}
  repaired+=c;if(!/\s/.test(c))previous=c;
 }
 try{return {plan:JSON.parse(repaired),repaired:true};}catch(e){throw new Error('Image plan configuration: invalid JSON after safe formatting repair: '+e.message);}
}

const input=$json||{},s=JSON.parse(JSON.stringify(input.state||input.review_state||input));
if(!s.topic?.topic_id||!s.article?.content_html||!s.article?.title||!s.run_id)throw new Error('Image pipeline configuration: missing article/topic/worker state');
