 if(!Array.isArray(images)||images.length!==4||new Set(images.map(x=>x.image?.role)).size!==4)throw new Error('Image pipeline configuration: recovery requires four unique generated images');
 return roles.map((role,index)=>{
  const r=images.find(x=>x.image?.role===role);
  if(!r||r.provider!=='openai'||r.image_status!=='complete'||typeof r.b64_json!=='string'||r.b64_json.length<100||r.image.index!==index)throw new Error('Image pipeline configuration: invalid saved generated image '+role);
  return {json:{...r,state:s,recovered_generated:true},pairedItem:{item:0}};
 });
}
const parsed=parseImagePlan(input.image_plan??input.output),p=parsed.plan;
if(!p||!Array.isArray(p.images)||p.images.length!==4||new Set(p.images.map(x=>x.role)).size!==4||p.images.some(x=>!roles.includes(x.role)))throw new Error('Image plan configuration: expected exactly four unique image roles');
s.image_plan_parse_status=parsed.repaired?'formatting_repaired':'valid';
const fileBase=String(s.topic.topic_id).replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,80);
return roles.map((role,index)=>{
 const im=p.images.find(x=>x.role===role);
 if(!im||typeof im.prompt!=='string'||im.prompt.length<20||im.prompt.length>1800||typeof im.alt_text!=='string'||!im.alt_text.trim())throw new Error('Image plan configuration: invalid prompt/alt text for '+role);
 const title_text=role==='featured'?s.article.title:im.alt_text,title_shaped=shapeArabic(wrapTitle(title_text));
 let altText=im.alt_text.trim();
 if((role==='featured'||role==='inline_1')&&!altText.includes(s.article.keyword))altText=s.article.keyword+' — '+altText;
 const image={role,index,title_text,title_shaped,prompt:im.prompt+'; serious editorial photography; navy and subtle gold palette; center composition for panoramic crop; no readable text, no logos, no watermark.',alt_text:altText.slice(0,240),file_name:fileBase+'-'+role+'.webp'};
 return {json:{state:s,image},pairedItem:{item:0}};
});

function crc32(buf){let c=0xffffffff;for(const byte of buf){c^=byte;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;}
function pngChunk(type,data){const t=Buffer.from(type),out=Buffer.alloc(data.length+12);out.writeUInt32BE(data.length,0);t.copy(out,4);data.copy(out,8);out.writeUInt32BE(crc32(Buffer.concat([t,data])),data.length+8);return out;}
const width=1200,height=630,stride=width*4+1,raw=Buffer.alloc(stride*height);
for(let y=0;y<height;y++){const alpha=Math.round(25+218*Math.pow(y/(height-1),1.3));for(let x=0;x<width;x++){const k=y*stride+1+x*4;raw[k]=12;raw[k+1]=30;raw[k+2]=51;raw[k+3]=alpha;}}
const deflate=[Buffer.from([0x78,0x01])];for(let start=0;start<raw.length;start+=65535){const len=Math.min(65535,raw.length-start),h=Buffer.alloc(5);h[0]=start+len===raw.length?1:0;h.writeUInt16LE(len,1);h.writeUInt16LE((~len)&65535,3);deflate.push(h,raw.subarray(start,start+len));}
