return $input.all().map((item,i)=>{const original=$('Decode Generated Image').itemMatching(i);return {json:original.json,binary:{image:original.binary.image,brand_logo:item.binary.brand_logo,brand_gradient},pairedItem:{item:i}};});

const x={...$json},now=Date.now();
if(now-Number(x.image_started_at)>20*60*1000)throw new Error('OpenAI image quota: image retry window exceeded; manual review required');
if(Number(x.slot_checks||0)>=60)throw new Error('OpenAI image quota: global image queue wait exceeded');
const slot=Math.floor(now/30000),range={sheetId:8707001,startRowIndex:0,endRowIndex:1,startColumnIndex:0,endColumnIndex:1};
const requests=[slot,slot+1].map(k=>({addNamedRange:{namedRange:{namedRangeId:'updates_oai_slot_'+k,name:'UPDATES_OAI_SLOT_'+k,range}}}));
return [{json:{...x,slot_checks:Number(x.slot_checks||0)+1,slot,slot_planned_at:now,requests},pairedItem:{item:0}}];

const x={...$('Plan OpenAI Image Slot').item.json},r=$json,status=Number(r.statusCode||0),body=r.body||{},msg=String(body.error?.message||r.error?.message||r.error||'');
