if(status===200&&Date.now()-x.slot_planned_at<10000)return [{json:{...x,slot_ready:true},pairedItem:{item:0}}];
const collision=status===400&&/already exists|duplicate/i.test(msg);
if(collision||status===200||status===429||status>=500||!status){
 const delay=Math.max(2,Math.ceil(((x.slot+1)*30000-Date.now())/1000))+2+Math.floor(Math.random()*4);
