throw new Error('OpenAI image configuration: global slot reservation failed HTTP '+status+' '+msg.slice(0,300));

const x={...$('OpenAI Image Slot Ready').item.json},r=$json,body=r.body??r,status=Number(r.statusCode||r.error?.statusCode||r.error?.httpCode||0);
