const headers=r.headers||{},error=body.error??r.error??{},code=String(error.code||error.type||''),msg=String(error.message||r.message||'Unknown response');
const requestId=String(headers['x-request-id']||headers['X-Request-Id']||'');
const finish=(kind,reason,action)=>{throw new Error('['+kind+'] OpenAI image: '+reason+' '+action+' (code='+String(code||status||'transport_error')+', request_id='+requestId+')');};
if(status>=200&&status<300){
 if(!Array.isArray(body.data)||body.data.length!==1||typeof body.data[0]?.b64_json!=='string')return finish('configuration','OpenAI رجّع نتيجة صورة ناقصة أو غير صالحة.','توقف المقال؛ يلزم مراجعة نتيجة الطلب قبل تكراره.');
 const b64=body.data[0].b64_json;
 if(b64.length<100||b64.length>30000000||!/^[A-Za-z0-9+/]+={0,2}$/.test(b64))return finish('configuration','OpenAI رجّع بيانات صورة غير صالحة.','توقف المقال للمراجعة.');
 return [{json:{state:x.state,image:x.image,provider:'openai',model:x.model,image_status:'complete',b64_json:b64,request_id:requestId,attempt:x.attempt,usage:body.usage||null},pairedItem:{item:0}}];
}
if(/insufficient_quota|credit_balance_exhausted|billing|spend_limit|usage_limit|quota.*exceeded|exceeded.*quota/i.test(code+' '+msg))return finish('quota','رصيد OpenAI أو حد الإنفاق المتاح لا يكفي لتوليد الصور.','راجع الرصيد وحدود الاستخدام في OpenAI. الدفعة ستتوقف ولن تتكرر الطلبات تلقائيًا.');
