if(transient){
 const attempt=Number(x.attempt||1),base=[60,180,600][attempt-1],retryAfter=headers['retry-after']||headers['Retry-After'];
 let serverDelay=0;
 if(retryAfter)serverDelay=/^\d+(\.\d+)?$/.test(String(retryAfter))?Number(retryAfter):Math.max(0,(Date.parse(retryAfter)-Date.now())/1000);
 for(const k of ['x-ratelimit-reset-requests','x-ratelimit-reset-tokens']){
