 if(attempt>=4)return finish('quota','استمر ضغط الطلبات أو عطل OpenAI بعد 3 محاولات إضافية للصورة.','توقف المقال والدفعة للمراجعة حتى لا تتكرر التكلفة على مقالات بديلة.');
 const wait=Math.ceil(Math.max(base,serverDelay))+Math.floor(Math.random()*11);
 if(Date.now()+wait*1000-Number(x.image_started_at)>20*60*1000)return finish('quota','OpenAI طلب انتظارًا أطول من مهلة إعادة المحاولة المسموحة للصورة.','أُوقف المقال؛ أعد المحاولة بعد انتهاء مهلة الخدمة.');
 return [{json:{...x,image_status:'retry',attempt:attempt+1,wait_seconds:wait,last_http_status:status,request_id:requestId},pairedItem:{item:0}}];
}
if(!status||status===408)return finish('ambiguous_write','انتهت مهلة الاتصال بـOpenAI أو انقطع الاتصال قبل تأكيد نتيجة الصورة.','أُوقف الطلب للمراجعة؛ لن يُرسل طلب مدفوع آخر تلقائيًا لأن نتيجة الطلب السابق غير مؤكدة.');
return finish('configuration','تعذّر طلب الصورة من OpenAI (HTTP '+status+'، '+code+'): '+msg.slice(0,350),'راجع إعدادات الموديل والطلب. أُوقفت الدفعة دون إعادة محاولات غير مفيدة.');
